@Component("exchangeRate-handler")
@ProcessingGroup("exchangeRate-processing-group")
public class ExchangeRateEventHandler {
	
	// core constructor
	ExchangeRateEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateExchangeRateEvent
     */
    @EventHandler
    public void handle( CreateExchangeRateEvent event) {
        entityManager.persist(new ExchangeRate(event.getExchangeRateId(), event.getBaseCurrency(), event.getQuoteCurrency(), event.getRate(), event.getAsOf(), event.getSource(), event.getUsedByQuotes()));
    }

    /*
     * @param	event UpdateExchangeRateEvent
     */
    @EventHandler
    public ExchangeRate handle( UpdateExchangeRateEvent event) {
    	entityManager.merge(new ExchangeRate(event.getExchangeRateId(), event.getBaseCurrency(), event.getQuoteCurrency(), event.getRate(), event.getAsOf(), event.getSource(), event.getUsedByQuotes()));
    }
    
    /*
     * @param	event DeleteExchangeRateEvent
     */
    @EventHandler
    public void on( DeleteExchangeRateEvent event) {
    	ExchangeRate entity = new ExchangeRate();
   
    	// ------------------------------------------
    	// apply the ExchangeRateId
    	// ------------------------------------------
    	entity.setExchangeRateId( event.getExchangeRateId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ExchangeRateRepository exchangeRateEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ExchangeRateEventHandler.class.getName());

}
